         return (
           <group key={asset.id}>
             <AssetModel
               asset={asset}
               status={status}
               isSelected={isSelected}
               isHovered={isHovered}
               onClick={() => handleClick(asset.id)}
               onPointerOver={() => {
                 hoverAsset(asset.id);
