     _incidentTimers.push(
       setTimeout(() => {
         set((s) => ({
           assetStatuses: {
             ...s.assetStatuses,
             "rack-c12": "warning",
             "rack-c13": "warning",
             "sensor-c1": "warning",
             "sensor-c2": "warning",
           },
           timelineEvents: [
             ...s.timelineEvents,
