               timestamp: formatTimestamp(new Date()),
               message: "Rack C12, C13 marked WARNING — inlet temp rising",
               severity: "warning",
             },
           ],
         }));
       }, 1800)
     );

     // Step 4: rack-c14 goes critical
     _incidentTimers.push(
       setTimeout(() => {
         set((s) => ({
           assetStatuses: {
             ...s.assetStatuses,
             "rack-c14": "critical",
