             },
           ],
         }));
       }, 2800)
     );

     // Step 5: dispatch recommendation
     _incidentTimers.push(
       setTimeout(() => {
         set((s) => ({
           timelineEvents: [
             ...s.timelineEvents,
             {
               id: "evt-5",
               timestamp: formatTimestamp(new Date()),
               message:
